=== bin/rollout
     1	#!/usr/bin/env bash
     2	# rollout — app configuration rollout for the payment hosts.
     3	#
     4	#   rollout apply RELEASE     check → apply → render → verify → record
     5	#   rollout show HOST         the rendered app.conf of HOST
     6	#   rollout hosts             active hosts and their pools
     7	#   rollout history           finished rollouts
     8	#
     9	# RELEASE is a file name under releases/ without .rel (e.g. r2026.10.08).
    10	# Configuration: conf/rollout.conf (ROLLOUT_* overrides).
    11	set -u
    12	export LC_ALL=C.UTF-8
    13	ROLLOUT_HOME=$(cd "$(dirname "$0")/.." && pwd)
    14	export ROLLOUT_HOME
    15	. "$ROLLOUT_HOME/steps/_env.sh"
    16	
    17	usage() { sed -n '3,10p' "$0" | sed 's/^# \{0,1\}//'; }
    18	
    19	cmd_apply() {
    20	  local rel=$1 step rc
    21	  for step in "$ROLLOUT_HOME"/steps/[0-9][0-9]-*.sh; do
    22	    bash "$step" "$rel"
    23	    rc=$?
    24	    if [ "$rc" -ne 0 ]; then
    25	      warn "step $(basename "$step") failed (exit $rc)"
    26	      return "$rc"
    27	    fi
    28	  done
    29	  log "rollout $rel complete"
    30	}
    31	
    32	cmd_show() {
    33	  local f
    34	  f=$(host_out "$1")
    35	  require_file "$f" "rendered config for $1"
    36	  cat "$f"
    37	}
    38	
    39	[ $# -ge 1 ] || { usage; exit 64; }
    40	cmd=$1; shift
    41	case "$cmd" in
    42	  apply)   [ $# -eq 1 ] || { usage; exit 64; }; cmd_apply "$1" ;;
    43	  show)    [ $# -eq 1 ] || { usage; exit 64; }; cmd_show "$1" ;;
    44	  hosts)   active_hosts ;;
    45	  history) history_show ;;
    46	  -h|--help|help) usage ;;
    47	  *) usage; exit 64 ;;
    48	esac
